const userJobsRaw = $('Find User Jobs').all().map(i => i.json);
const jobsRaw = $('Find Jobs').all().map(i => i.json);

// Drop empty placeholder items produced by alwaysOutputData when there are no rows
const userJobs = userJobsRaw.filter(r => r && r.user_id);

const jobsById = {};
for (const j of jobsRaw) {
  if (j && j.job_id) jobsById[j.job_id] = j;
}

function parseArr(v) {
  if (v === null || v === undefined || v === '') return [];
  if (Array.isArray(v)) return v;
  try {
    const parsed = JSON.parse(v);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

// Interview-prep plan written by get_materials into user_jobs.prep_* (null until prep_status = 'ready')
function prepOf(uj) {
  if (uj.prep_status !== 'ready') return null;
  return {
    role_type: uj.prep_role_type ?? null,
    skill_gaps: parseArr(uj.prep_skill_gaps_json),            // [{skill, why}]
    courses: parseArr(uj.prep_courses_json),                   // [{title, url, why}]
    practice: parseArr(uj.prep_practice_json),                 // [{title, url, type, why}]
    interview_insights: parseArr(uj.prep_interview_insights_json), // [{insight, source_url}]
    likely_questions: parseArr(uj.prep_likely_questions_json), // [{question, answer_hint, source}]
    plan: parseArr(uj.prep_plan_json),                         // [{day, focus, tasks[]}]
    plan_markdown: uj.prep_plan_markdown ?? null,
    data_quality: uj.prep_data_quality ?? null,
    updated_at: uj.prep_updated_at ?? null,
  };
}

const result = [];
for (const uj of userJobs) {
  if (uj.hidden === true) continue;
  const job = jobsById[uj.job_id];
  if (!job) continue;
  if (job.is_active === false) continue;

  result.push({
    id: job.job_id,
    title: job.title ?? null,
    company_name: job.company_name ?? null,
    company_url: job.company_url ?? null,
    job_url: job.job_url ?? null,
    location: job.location ?? null,
    remote_type: job.remote_type ?? null,
    employment_type: job.employment_type ?? null,
    description: job.description ?? null,
    seniority: job.seniority ?? null,
    salary_min: job.salary_min ?? null,
    salary_max: job.salary_max ?? null,
    salary_currency: job.salary_currency ?? null,
    published_at: job.published_at ?? null,

    match_score: uj.match_score ?? null,
    priority_score: uj.priority_score ?? null,
    status: uj.status ?? null,
    match_reason: uj.match_reason ?? null,
    company_risk_score: uj.company_risk_score ?? null,
    saved: uj.saved ?? false,
    applied_at: uj.applied_at ?? null,
    interview_at: uj.interview_at ?? null,

    matched_skills: parseArr(uj.matched_skills_json),
    missing_skills: parseArr(uj.missing_skills_json),

    // 'ready' when the interview-prep plan exists, otherwise 'pending' (get_materials still has to run)
    prep_status: uj.prep_status === 'ready' ? 'ready' : 'pending',
    prep: prepOf(uj),
  });
}

result.sort((a, b) => {
  const p = (b.priority_score ?? 0) - (a.priority_score ?? 0);
  if (p !== 0) return p;
  return (b.match_score ?? 0) - (a.match_score ?? 0);
});

return [{ json: { success: true, count: result.length, jobs: result } }];
